// Art Home launcher, run in a fake TV (fake-tv.cjs):  node --test art-home/tests/
const assert = require('node:assert/strict');
const test = require('node:test');
const { boot } = require('./fake-tv.cjs');

// the order of index.html (settings.js is generated by build.sh; the fake TV passes it as opts.settings)
const SCRIPTS = ['aero-bridge.js', 'upstream:js/homewatch.js', 'i18n.js', 'cameras.js', 'app.js', 'alerts.js', 'energy.js'];

const CAMERAS = {
  frigate_url: 'http://frigate', go2rtc_url: 'http://go2rtc',
  list: [
    { name: 'Front door', frigate: 'front', stream: 'front', sub: 'front_sub' },
    { name: 'Garden', frigate: 'garden', stream: 'garden', sub: 'garden_sub' },
    { name: 'Yard', frigate: 'yard', stream: 'yard', sub: '' },
    { name: 'Side', frigate: 'side', stream: 'side', sub: 'side_sub' },
    { name: 'Drive', frigate: 'drive', stream: 'drive', sub: 'drive_sub' }
  ]
};
const WORKS = [1, 2, 3].map((i) => ({ id: i, title: 'Work ' + i, artist: 'Artist', file: 'w' + i + '.jpg', width: 16, height: 9, color: '#336699' }));

function home(extra = {}) {
  return { works: WORKS, apps: [{ name: 'Tube', id: 'tube.app', color: '#f00', glyph: '▶' }], cameras: CAMERAS,
    energy: {}, alerts: {}, weather: null, rotate_s: 90, frame_after_s: 20, ...extra };
}

function fakeTizen() {
  const launched = [];
  return {
    launched,
    application: {
      launch: (id) => launched.push(id),
      getAppsInfo: (ok) => ok([{ id: 'tube.app' }, { id: 'other.app' }]),
      launchAppControl: () => launched.push('service')
    },
    ApplicationControl: function (op) { this.op = op; },
    tvinputdevice: { registerKey: () => {} }
  };
}

// server(alerts) → the fake Art Home server: /api/home, /api/alerts by `since`, /api/turn-off
function tv({ homeData = home(), alerts = () => ({ seq: 0, alerts: [] }), images, tizen, locale, now } = {}) {
  const t = boot(SCRIPTS, {
    locale, tizen, now, images,
    server(method, url) {
      if (url.endsWith('/api/home')) return homeData ? { status: 200, body: homeData } : null;
      if (url.includes('/api/alerts?since=')) return { status: 200, body: alerts(Number(url.split('since=')[1])) };
      if (url.includes('/api/turn-off')) return { status: 200, body: { turned_off: false } };
      if (url.startsWith('http://127.0.0.1:47790/')) return { status: 200, body: { leaving: true } };
      return { status: 404, body: '' };
    }
  });
  t.advance(50);   // first /api/home answered
  return t;
}
const names = (t) => t.elements.apps.children.map((c) => /class="name">([^<]*)</.exec(c.innerHTML)[1]);
const focused = (t) => t.elements.apps.children.findIndex((c) => c.classList.contains('focus'));

/* ---------- home screen ---------- */

test('the first key only wakes the screen; then arrows move the focus and wrap', () => {
  const t = tv();
  assert.ok(t.document.body.classList.contains('frame'), 'arrival starts in frame mode');
  assert.equal(t.key(39).prevented, true);
  assert.equal(focused(t), 0, 'the waking key did nothing else');
  t.key(39);
  assert.equal(focused(t), 1);
  t.key(39); t.key(39);
  assert.equal(focused(t), 0, 'wraps around');
  t.advance(20000);
  assert.ok(t.document.body.classList.contains('frame'), '20 s idle → frame mode again');
});

test('the app row ends with Cameras and Samsung, Cameras only when the server lists cameras', () => {
  assert.deepEqual(names(tv()), ['Tube', 'Cameras', 'Samsung']);
  assert.deepEqual(names(tv({ homeData: home({ cameras: { list: [] } }) })), ['Tube', 'Samsung']);
});

test('the credit line escapes what comes from the museum', () => {
  const works = [{ ...WORKS[0], title: '<img src=x onerror=alert(1)>', artist: 'A & B' }];
  const t = tv({ homeData: home({ works }) });
  t.advance(100);
  assert.match(t.elements.credit.innerHTML, /^<b>&lt;img src=x onerror=alert\(1\)&gt;<\/b>A &amp; B/);
});

test('with every image failing it tries one lap, then waits for the next rotation (no request storm)', () => {
  const t = tv({ images: (url) => !url.includes('/art/') });
  t.advance(10000);
  const art = () => t.imageLoads.filter((u) => u.includes('/art/')).length;
  assert.equal(art(), 3, 'one try per work');
  t.advance(85000);   // past the 90 s rotation
  assert.equal(art(), 6, 'the rotation tries one more lap');
});

test('one bad image skips to the next work', () => {
  const t = tv({ images: (url) => !url.endsWith('/w1.jpg') });
  t.advance(1000);
  assert.match(t.elements.credit.innerHTML, /Work 2/);
});

test('without the server it keeps the clock and asks again every minute', () => {
  const t = tv({ homeData: null });
  assert.match(t.elements.clock.textContent, /^12:00$/);
  t.advance(60000);
  assert.equal(t.requests.filter((r) => r.url.endsWith('/api/home')).length, 2);
});

test('weather appears only with a temperature', () => {
  const t = tv({ homeData: home({ weather: { state: 'rainy', text: 'Rain', temperature: 18.6 } }) });
  assert.equal(t.elements.weather.hidden, false);
  assert.equal(t.elements['weather-temp'].textContent, '19°');
  assert.equal(tv().elements.weather.hidden, true);
});

test('in the desktop preview, Samsung shows our own (translated) message', () => {
  const t = tv({ locale: 'pt-BR' });
  t.key(37);            // wakes
  t.key(37);            // → Samsung (last)
  t.key(13);
  assert.equal(t.elements.toast.textContent, 'Prévia: abriria a home da Samsung');
  assert.deepEqual(names(t), ['Tube', 'Câmeras', 'Samsung']);
});

/* ---------- AeroTizen's homewatch.js on top of our bridge ---------- */

test('on the TV: starts the Home service, reports the apps and watches the app it opens', () => {
  const tizen = fakeTizen();
  const t = tv({ tizen });
  const service = t.requests.map((r) => r.url).filter((u) => u.startsWith('http://127.0.0.1:47790/'));
  assert.ok(tizen.launched.includes('service'), 'service started');
  assert.ok(service.includes('http://127.0.0.1:47790/apps?ids=tube.app,other.app'));
  t.key(13); t.key(13);   // wake, then open "Tube"
  assert.ok(t.requests.some((r) => r.url === 'http://127.0.0.1:47790/watch?id=tube.app'));
  assert.equal(tizen.launched.at(-1), 'tube.app');
});

test('the bridge gives homewatch.js everything it uses', () => {
  const t = boot(['aero-bridge.js', 'upstream:js/homewatch.js'], { tizen: fakeTizen() });
  const hw = t.window.AeroTizen.homewatch;
  for (const fn of ['start', 'watch', 'reportApps', 'useSamsungHome', 'isLeaving']) assert.equal(typeof hw[fn], 'function', fn);
  hw.useSamsungHome();
  t.advance(10);
  assert.ok(t.requests.some((r) => r.url === 'http://127.0.0.1:47790/leave'));
});

/* ---------- detection pop-up ---------- */

function alertFeed(list) {
  // list: alerts in order; the server answers everything after `since`
  let seq = list.length;
  return { feed: (since) => ({ seq, alerts: since < 0 ? [] : list.filter((a) => a.seq > since) }), restart() { seq = 0; list.length = 0; } };
}
const alert = (seq, camera = 'front', label = 'person') => ({ seq, id: 'e' + seq, camera, label, start: 0, photo: 'p' + seq, thumbnail: 't' + seq });

test('opening shows nothing of the past; a new detection shows a translated card', () => {
  const list = [alert(1)];
  const f = alertFeed(list);
  const t = tv({ alerts: f.feed, locale: 'pt-BR' });
  t.advance(100);
  assert.ok(!t.elements.alert.classList.contains('shown'), 'the past is not shown');
  list.push(alert(2, 'garden', 'dog'));
  t.advance(2100);
  assert.ok(t.elements.alert.classList.contains('shown'));
  assert.equal(t.elements['alert-title'].textContent, 'Cachorro · Garden');
  t.advance(15000);
  assert.ok(!t.elements.alert.classList.contains('shown'), 'hides after show_s');
});

test('cards that arrive together are shown one after the other', () => {
  const list = [];
  const t = tv({ alerts: (since) => ({ seq: list.length, alerts: since < 0 ? [] : list.filter((a) => a.seq > since) }) });
  t.advance(100);
  list.push(alert(1, 'front'), alert(2, 'garden'));
  t.advance(2100);
  assert.match(t.elements['alert-title'].textContent, /Front door/);
  t.advance(15700);
  assert.match(t.elements['alert-title'].textContent, /Garden/);
});

test('after the server restarts (sequence back to 0) new cards still arrive', () => {
  let list = [alert(1), alert(2), alert(3)];
  const t = tv({ alerts: (since) => ({ seq: list.length, alerts: since < 0 ? [] : list.filter((a) => a.seq > since) }) });
  t.advance(100);
  list = [];            // restarted: empty, seq 0
  t.advance(2100);
  list = [alert(1, 'garden')];
  t.advance(2100);
  assert.ok(t.elements.alert.classList.contains('shown'));
  assert.match(t.elements['alert-title'].textContent, /Garden/);
});

test('the red key while a card is on screen opens that camera live', () => {
  const list = [];
  const t = tv({ tizen: fakeTizen(), alerts: (since) => ({ seq: list.length, alerts: since < 0 ? [] : list.filter((a) => a.seq > since) }) });
  t.advance(100);
  list.push(alert(1, 'yard'));
  t.advance(2100);
  t.key(403);
  assert.equal(t.elements['cam-full'].hidden, false);
  assert.equal(t.elements['cam-video'].src, 'http://go2rtc/api/stream.mp4?src=yard');
  assert.ok(!t.elements.alert.classList.contains('shown'));
});

/* ---------- cameras ---------- */

function openCameras(t) {
  t.key(13);                      // wake
  t.key(39);                      // → Cameras (after "Tube")
  t.key(13);
  assert.equal(t.elements.cameras.hidden, false);
}
const camFocus = (t) => t.elements['cam-grid'].children.findIndex((c) => c.classList.contains('focus'));

test('camera grid: arrows by tile, up/down by row, never off the grid', () => {
  const t = tv();
  openCameras(t);
  t.key(39); assert.equal(camFocus(t), 1);
  t.key(40); assert.equal(camFocus(t), 4);
  t.key(40); assert.equal(camFocus(t), 4);
  t.key(38); t.key(38); assert.equal(camFocus(t), 1);
  t.key(10009);
  assert.equal(t.elements.cameras.hidden, true);
});

test('full screen falls back to the sub stream, says when there is no video, and Back releases it', () => {
  const t = tv();
  openCameras(t);
  t.key(13);
  const v = t.elements['cam-video'];
  assert.equal(v.src, 'http://go2rtc/api/stream.mp4?src=front');
  t.advance(8000);
  assert.equal(v.src, 'http://go2rtc/api/stream.mp4?src=front_sub');
  t.advance(8000);
  assert.equal(t.elements['cam-full-note'].textContent, 'no video right now');
  t.key(10009);
  assert.equal(t.elements['cam-full'].hidden, true);
  assert.equal(v.src, '', 'the go2rtc connection is released');
  assert.equal(t.elements.cameras.hidden, false, 'back on the grid');
});

test('a tile says "no signal" after 3 failed frames and recovers on the next good one', () => {
  let down = true;
  const t = tv({ images: (url) => !(down && url.includes('/api/front/latest.jpg')) });
  openCameras(t);
  const tile = t.elements['cam-grid'].children[0];
  t.advance(1500 * 3 + 100);
  assert.equal(tile.querySelector('.cam-down').hidden, false);
  down = false;
  t.advance(1600);
  assert.equal(tile.querySelector('.cam-down').hidden, true);
});

/* ---------- energy ---------- */

const dim = (t) => t.elements.dimmer.style.opacity;

test('arrival starts dim; any key brings full light', () => {
  const t = tv();
  assert.equal(dim(t), '0.5');
  t.key(13);
  assert.equal(dim(t), '0');
});

test('idle for dim_after_min dims the artwork', () => {
  const t = tv();
  t.key(13);
  t.advance(30.5 * 60000);   // the check runs every 30 s
  assert.equal(Number(dim(t)).toFixed(2), '0.55');
});

test('at night, idle, it asks the server to turn off once; a key re-arms it', () => {
  const t = tv({ homeData: home({ energy: { turn_off: true } }), now: new Date(2026, 0, 1, 23, 0).getTime() });
  const asks = () => t.requests.filter((r) => r.method === 'POST' && r.url.includes('/api/turn-off')).length;
  t.key(13);
  t.advance(119 * 60000);
  assert.equal(asks(), 0);
  t.advance(2 * 60000);
  assert.equal(asks(), 1);
  t.advance(60 * 60000);
  assert.equal(asks(), 1, 'asked once');
  t.key(13);
  t.advance(121 * 60000);
  assert.equal(asks(), 2);
});

test('never asks to turn off during the day, or when turn_off is off', () => {
  for (const [energy, hour] of [[{ turn_off: true }, 14], [{ turn_off: false }, 1]]) {
    const t = tv({ homeData: home({ energy }), now: new Date(2026, 0, 1, hour, 0).getTime() });
    t.key(13);
    t.advance(200 * 60000);
    assert.equal(t.requests.filter((r) => r.url.includes('/api/turn-off')).length, 0, JSON.stringify(energy) + ' ' + hour);
  }
});

test('with the cameras open the screen never dims', () => {
  const t = tv();
  openCameras(t);
  t.advance(40 * 60000);
  assert.equal(dim(t), '0');
});
